number.script:
          function onInit()
            local sDBnode = window.getDatabaseNode();           
            nLevel = DB.getValue(sDBnode,"level",1);

            -- use DB value as source of truth
            nLevel = CompanionData.validateLevel(nLevel);
            setValue(nLevel);
            
            -- updateCosts();
          end
          function onValueChanged()
            local nLevel = CompanionData.validateLevel(getValue());
            DB.setValue(window.getDatabaseNode(),"level","number",nLevel);

            updateCosts();
            window.attackbonus_base.updateBAB();
          end
          function updateCosts()
            local sDBnode = window.getDatabaseNode();
            local nLevel = getValue() or 1;

            -- in case the level or HP were not set yet
            DB.setValue(sDBnode,"level","number",nLevel);
            local nHP = CompanionData.getLevelHP(nLevel);

            -- set the window so it can update the DB node
            window.current_maxHP.setValue(nHP);

            local nCost = CompanionData.getLevelCost(nLevel);
            window.cost_current.setValue(nCost);

            local nUpgradeCost = CompanionData.getLevelCost(nLevel + 1);
            window.cost_upgrade.setValue(nUpgradeCost);
          end

buttoncontrol.script:
function onButtonPress()
  local nLevel = window.current_level.getValue();
  nLevel = CompanionData.validateLevel(nLevel + 1);
  window.current_level.setValue(nLevel);
end

function onButtonPress()
  local nLevel = window.current_level.getValue();
  nLevel = CompanionData.validateLevel(nLevel - 1);
  window.current_level.setValue(nLevel);
end

number.script:
          function onValueChanged()
            local sDBnode = window.getDatabaseNode();
            local nMaxHP = getValue() or 0;

            local nodeHP = DB.getChild(sDBnode,"hp");
            DB.setValue(nodeHP, "total",   "number", nMaxHP);
            DB.setValue(nodeHP, "current", "number", nMaxHP);
            Debug.console("Set Max HP to " .. nMaxHP);
          end

function onValueChanged()
  local sDBnode = window.getDatabaseNode();
  local nCurrentCost = getValue() or 0;
  DB.setValue(sDBnode,"currentcost","number",nCurrentCost);
  Debug.console("Set Current Cost to " .. nCurrentCost);
end

function onValueChanged()
  local sDBnode = window.getDatabaseNode();
  local nCurrentCost = window.cost_current.getValue() or 0;
  local nUpgradeCost = getValue() or 0;
  local nTrainingCost = nUpgradeCost - nCurrentCost;
  DB.setValue(sDBnode,"traincost","number",nTrainingCost);
  Debug.console("Set Training Cost to " .. nTrainingCost);
end

button_stringcycler.script:
function onValueChanged()
  local sStat = getValue();
  Debug.console("Primary Stat selected: " .. sStat);
end

function onValueChanged()
  local sStat = getValue();
  Debug.console("Secondary Stat selected: " .. sStat);
end

buttoncontrol.script:
function onButtonPress()
  Debug.console("Committing ability score changes...");
  
  local sDBnode = window.getDatabaseNode();
  local nLevel = window.current_level.getValue() or 1;
  local sPrimaryStat = window.stat_primary.getStringValue();
  local sSecondaryStat = window.stat_secondary.getStringValue();
  
  -- Validate that primary and secondary are different
  if sPrimaryStat == sSecondaryStat then
    Debug.console("ERROR: Primary and Secondary stats must be different!");
    return;
  end
  
  -- List of all ability scores
  local abilities = {"charisma", "constitution", "dexterity", "intelligence", "strength", "wisdom"};
  
  -- Step 1: Reset all ability scores to defaults
  -- All scores start at 10 (+0 bonus) except Intelligence which is 2 (-4 bonus)
  for _, ability in ipairs(abilities) do
    local nodeAbility = DB.getChild(sDBnode, "abilities." .. ability);
    local defaultScore = (ability == "intelligence") and 2 or 10;
    local defaultBonus = CompanionData.getStatBonus(defaultScore);
    
    DB.setValue(nodeAbility, "base", "number", defaultScore);
    DB.setValue(nodeAbility, "score", "number", defaultScore);
    DB.setValue(nodeAbility, "bonus", "number", defaultBonus);
    
    Debug.console("Reset " .. ability .. " to score " .. defaultScore .. " (bonus " .. defaultBonus .. ")");
  end
  
  -- Step 2: Apply primary stat bonus
  if sPrimaryStat ~= "" then
    local nPrimaryBonus = CompanionData.getLevelFirstAbility(nLevel);
    local nPrimaryScore = CompanionData.getScoreFromBonus(nPrimaryBonus);
    
    local nodePrimary = DB.getChild(sDBnode, "abilities." .. sPrimaryStat);
    DB.setValue(nodePrimary, "base", "number", nPrimaryScore);
    DB.setValue(nodePrimary, "score", "number", nPrimaryScore);
    DB.setValue(nodePrimary, "bonus", "number", nPrimaryBonus);
    
    Debug.console("Set Primary Stat " .. sPrimaryStat .. " to score " .. nPrimaryScore .. " (bonus " .. nPrimaryBonus .. ")");
  end
  
  -- Step 3: Apply secondary stat bonus
  if sSecondaryStat ~= "" then
    local nSecondaryBonus = CompanionData.getLevelSecondAbility(nLevel);
    local nSecondaryScore = CompanionData.getScoreFromBonus(nSecondaryBonus);
    
    local nodeSecondary = DB.getChild(sDBnode, "abilities." .. sSecondaryStat);
    DB.setValue(nodeSecondary, "base", "number", nSecondaryScore);
    DB.setValue(nodeSecondary, "score", "number", nSecondaryScore);
    DB.setValue(nodeSecondary, "bonus", "number", nSecondaryBonus);
    
    Debug.console("Set Secondary Stat " .. sSecondaryStat .. " to score " .. nSecondaryScore .. " (bonus " .. nSecondaryBonus .. ")");
  end
  
  Debug.console("Ability score commit complete!");
end

number.script:
          function updateBAB()
            -- read BaB
            local nLevel = window.current_level.getValue() or 1;
            local nBAB = CompanionData.getLevelAttack(nLevel);
            setValue(nBAB);
          end

          function onValueChanged()
            local nBAB = getValue() or 0;
            -- write BaB
            local sDBnode = window.getDatabaseNode();
            DB.setValue(sDBnode,"attackbonus.base","number",nBAB);
            Debug.console("Set Base Attack Bonus to " .. nBAB);
          end

button_stringcycler.script:
        function onValueChanged()
          local sSaveType = getStringValue();
          local nSaveBonus = 0;
          local nLevel = window.current_level.getValue() or 1;          
          Debug.console("Fortitude Save Type selected: " .. sSaveType);

          -- get the good or base save from reference data then write to DB
          if sSaveType == "" then
            Debug.console("No save type selected, skipping.");
            return;
          elseif sSaveType == "good"  then
            nSaveBonus = CompanionData.getLevelGoodSave(nLevel);
          elseif sSaveType == "poor" then
            nSaveBonus = CompanionData.getLevelPoorSave(nLevel);
          end

          -- DB save to saves.fortitude.base
          local sDBnode = window.getDatabaseNode();
          DB.setValue(sDBnode,"saves.fortitude.base","number",nSaveBonus);
        end

